public int migratoryBirds(List<Integer> arr) {
    int bestId = 1;
    int bestCount = -1;
    for (int id = 1; id <= 5; id++) {
        int c = 0;
        for (int t : arr) {
            if (t == id) {
                c++;
            }
        }
        if (c > bestCount) {
            bestCount = c;
            bestId = id;
        }
    }
    return bestId;
}

