public int migratoryBirds(List<Integer> arr) {
    int[] count = new int[6];
    for (int t : arr) {
        count[t]++;
    }
    int bestId = 1;
    for (int id = 2; id <= 5; id++) {
        if (count[id] > count[bestId]) {
            bestId = id;
        }
    }
    return bestId;
}

